    perform public.billing_sales_inventory_finalize((line->>'id')::uuid,business,data_mode);
   end loop;
   if kind<>'transfer' and total>0 then counter=case kind when 'opening' then config.opening_account when 'receipt' then config.clearing_account when 'supplier-return' then config.clearing_account when 'dispatch' then config.cogs_account when 'customer-return' then config.cogs_account else config.adjustment_account end;debit=case when kind in ('opening','receipt','customer-return','adjust-in') then config.stock_account else counter end;credit=case when kind in ('opening','receipt','customer-return','adjust-in') then counter else config.stock_account end;journal=(public.billing_ledger_commit(business,data_mode,event_id,request,jsonb_build_object('date',day,'kind','manual','description','Inventory '||kind||': '||left(reason,900),'entries',jsonb_build_array(jsonb_build_object('account_id',debit,'debit',total::text,'credit','0'),jsonb_build_object('account_id',credit,'debit','0','credit',total::text)))))->'batch';end if;
   insert into public.billing_inventory_postings(event_id,business_id,demo,batch_id,financial_effect) values(event_id,business,data_mode,(journal->>'id')::uuid,case when kind='transfer' then 'warehouse-transfer-zero-net' when total=0 then 'reviewed-zero-cost' else 'posted' end);
   result=jsonb_build_object('eventId',event_id,'kind',kind,'date',day,'valuation',total::text,'journal',journal,'unitFactors',(select jsonb_agg(to_jsonb(u)||jsonb_build_object('factor',u.factor::text)) from public.billing_inventory_units u where u.business_id=business and u.demo=data_mode and u.id in(select (value->>'unitId')::uuid from jsonb_array_elements(command_data->'lines'))),'movements',(select jsonb_agg(to_jsonb(m)||jsonb_build_object('quantity',m.quantity::text,'value',m.value::text) order by m.id) from public.billing_inventory_movements m where m.event_id=inventory_cmd.event_id),'consumptions',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('quantity',c.quantity::text,'value',c.value::text) order by c.id) from public.billing_inventory_consumptions c where c.event_id=inventory_cmd.event_id),'[]'::jsonb),'layers',coalesce((select jsonb_agg(to_jsonb(l)||jsonb_build_object('quantity',l.quantity::text,'value',l.value::text) order by l.sequence) from public.billing_inventory_layers l join public.billing_inventory_movements m on m.id=l.movement_id where m.event_id=inventory_cmd.event_id),'[]'::jsonb),'replayed',false);
  end if;
 end if;
 insert into public.billing_inventory_commands(business_id,demo,command_id,actor_id,request,result) values(business,data_mode,command_id,auth.uid(),request,result);insert into public.billing_inventory_audit(business_id,demo,actor_id,action,details) values(business,data_mode,auth.uid(),'inventory.'||action,jsonb_build_object('eventId',event_id,'result',result));insert into public.billing_inventory_outbox(business_id,demo,command_id,topic,payload) values(business,data_mode,command_id,'inventory.'||action,result);return result;
end$$;

create function public.billing_inventory_journal_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare source uuid;qty numeric;
begin
 if new.reverses_id is null then return new;end if;
 if exists(select 1 from public.billing_inventory_postings where batch_id=new.reverses_id) then raise exception 'Correct stock through traceable return/adjustment commands; a generic GL reversal cannot bypass stock quantities and costs';end if;
 select id into source from public.billing_vendor_bills where issued_batch=new.reverses_id;
 if source is not null and exists(select 1 from public.billing_inventory_source_lines s where s.source_kind='vendor-bill' and s.source_id=source and(exists(select 1 from public.billing_inventory_movements m where m.source_line=s.id and m.date>new.date) or coalesce((select sum(m.quantity) from public.billing_inventory_movements m where m.source_line=s.id),0)<>0)) then raise exception 'Return/correct linked received stock before reversing its purchase-clearing bill';end if;return new;
end$$;
create trigger inventory_journal_source_guard before insert on public.billing_ledger_batches for each row execute function public.billing_inventory_journal_guard();
create function public.billing_inventory_document_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from public.billing_inventory_source_lines s where s.source_kind='issued-document' and s.source_id=new.document_id and(exists(select 1 from public.billing_inventory_movements m where m.source_line=s.id and m.date>new.date) or exists(select 1 from public.billing_inventory_reservations r where r.source_line=s.id and r.date>new.date) or coalesce((select sum(m.quantity) from public.billing_inventory_movements m where m.source_line=s.id),0)<>0 or coalesce((select sum(r.quantity*case when r.kind='reserve' then 1 else -1 end) from public.billing_inventory_reservations r where r.source_line=s.id),0)<>0)) then raise exception 'Return/correct fulfillment and release source reservations before cancelling this document';end if;return new;
end$$;
create trigger inventory_document_source_guard before insert on public.billing_document_cancellations for each row execute function public.billing_inventory_document_guard();

create function public.billing_inventory_reconciliation(business uuid,data_mode boolean,as_of date,event_ceiling bigint default null,ledger_ceiling bigint default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare config public.billing_inventory_configs;movement_value numeric(30,2)=0;layer_value numeric(30,2)=0;stock_ledger numeric(30,2)=0;clearing_ledger numeric(30,2)=0;clearing_expected numeric(30,2)=0;bill_value numeric(30,2)=0;credit_value numeric(30,2)=0;receipt_value numeric(30,2)=0;unmatched bigint=0;max_event bigint;max_ledger bigint;
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='Inventory reconciliation unavailable in this business';end if;
 if data_mode is null or as_of is null or not isfinite(as_of) then raise exception 'Choose a valid stock valuation date/data mode';end if;
 select * into config from public.billing_inventory_configs where business_id=business and demo=data_mode;
 if config.business_id is null then return jsonb_build_object('configured',false,'reviewStatus','unreviewed');end if;
 select coalesce(max(sequence),0) into max_event from public.billing_inventory_events where business_id=business and demo=data_mode;
 select next_number-1 into max_ledger from public.billing_ledger_configs where business_id=business and demo=data_mode;event_ceiling=coalesce(event_ceiling,max_event);ledger_ceiling=coalesce(ledger_ceiling,max_ledger);
 if event_ceiling<0 or event_ceiling>max_event or ledger_ceiling<0 or ledger_ceiling>max_ledger then raise exception 'Inventory reconciliation snapshot is invalid';end if;
 select coalesce(sum(m.value),0) into movement_value from public.billing_inventory_movements m join public.billing_inventory_events e on e.id=m.event_id where m.business_id=business and m.demo=data_mode and m.date<=as_of and e.sequence<=event_ceiling;
 select coalesce(sum(l.value),0) into layer_value from public.billing_inventory_layers l join public.billing_inventory_movements m on m.id=l.movement_id join public.billing_inventory_events e on e.id=m.event_id where l.business_id=business and l.demo=data_mode and l.date<=as_of and e.sequence<=event_ceiling;
 select layer_value-coalesce(sum(c.value),0) into layer_value from public.billing_inventory_consumptions c join public.billing_inventory_events e on e.id=c.event_id where c.business_id=business and c.demo=data_mode and c.date<=as_of and e.sequence<=event_ceiling;
 select coalesce(sum(e.debit-e.credit) filter(where e.account_id=config.stock_account),0),coalesce(sum(e.debit-e.credit) filter(where e.account_id=config.clearing_account),0) into stock_ledger,clearing_ledger from public.billing_ledger_entries e join public.billing_ledger_batches b on b.id=e.batch_id where e.business_id=business and e.demo=data_mode and b.date<=as_of and substring(b.number from '([0-9]+)$')::bigint<=ledger_ceiling;
 select coalesce(sum((b.data->>'subtotal')::numeric) filter(where j.date<=as_of and substring(j.number from '([0-9]+)$')::bigint<=ledger_ceiling),0)-coalesce(sum((b.data->>'subtotal')::numeric) filter(where r.date<=as_of and substring(r.number from '([0-9]+)$')::bigint<=ledger_ceiling),0) into bill_value from public.billing_vendor_bills b join public.billing_ledger_batches j on j.id=b.issued_batch left join public.billing_ledger_batches r on r.reverses_id=b.issued_batch where b.business_id=business and b.demo=data_mode and b.data->>'accountId'=config.clearing_account::text;
 select coalesce(sum(c.subtotal) filter(where j.date<=as_of and substring(j.number from '([0-9]+)$')::bigint<=ledger_ceiling),0)-coalesce(sum(c.subtotal) filter(where r.date<=as_of and substring(r.number from '([0-9]+)$')::bigint<=ledger_ceiling),0) into credit_value from public.billing_vendor_credits c join public.billing_ledger_batches j on j.id=c.batch_id left join public.billing_ledger_batches r on r.reverses_id=c.batch_id where c.business_id=business and c.demo=data_mode and c.snapshot->'sourceBill'->>'accountId'=config.clearing_account::text;
 select coalesce(sum(m.value),0) into receipt_value from public.billing_inventory_movements m join public.billing_inventory_events e on e.id=m.event_id where m.business_id=business and m.demo=data_mode and m.date<=as_of and e.sequence<=event_ceiling and e.kind in ('receipt','supplier-return');clearing_expected=bill_value-credit_value-receipt_value;
 select count(*) into unmatched from public.billing_inventory_layers l join public.billing_inventory_movements m on m.id=l.movement_id join public.billing_inventory_events e on e.id=m.event_id left join public.billing_inventory_source_lines s on s.id=l.source_line where l.id=l.root_layer and l.business_id=business and l.demo=data_mode and l.date<=as_of and e.sequence<=event_ceiling and e.kind='receipt' and(s.id is null or s.source_kind<>'vendor-bill') and l.quantity>coalesce((select sum(c.quantity) from public.billing_inventory_consumptions c join public.billing_inventory_layers x on x.id=c.layer_id join public.billing_inventory_events z on z.id=c.event_id where x.root_layer=l.id and z.kind='supplier-return' and c.date<=as_of and z.sequence<=event_ceiling),0);
 return jsonb_build_object('configured',true,'currency',config.currency,'asOf',as_of,'eventCeiling',event_ceiling::text,'ledgerCeiling',ledger_ceiling::text,'movementValue',movement_value::text,'layerValue',layer_value::text,'stockLedger',stock_ledger::text,'stockDifference',(stock_ledger-movement_value)::text,'layerDifference',(layer_value-movement_value)::text,'clearingExpected',clearing_expected::text,'clearingLedger',clearing_ledger::text,'clearingDifference',(clearing_ledger-clearing_expected)::text,'unmatchedReceiptCount',unmatched,'arithmeticAgrees',movement_value=layer_value and movement_value=stock_ledger and clearing_expected=clearing_ledger and unmatched=0,'reviewStatus','unreviewed','limitations',jsonb_build_array('Mechanical FIFO/source/GL comparison, not accountant verification.','Legacy item quantities remain untouched and are not opening stock.','Unmatched receipts and purchase-clearing balances require bill/source review; negative clearing is not invented as a settled supplier obligation.','Backdated changes affecting frozen FIFO consumptions require reviewed recost/correction; no existing COGS is silently rewritten.'));
end$$;

create function public.billing_inventory_read(business uuid,data_mode boolean,as_of date,item_id uuid default null,after_sku text default null,page_size integer default 100,event_ceiling bigint default null,ledger_ceiling bigint default null,barcode_search text default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare stock jsonb='[]';config public.billing_inventory_configs;accounts jsonb;warehouses jsonb;items jsonb;units jsonb='[]';lots jsonb='[]';movements jsonb='[]';layers jsonb='[]';consumptions jsonb='[]';reservations jsonb='[]';sources jsonb='[]';selected public.billing_inventory_items;reconciliation jsonb;count bigint;max_event bigint;max_ledger bigint;next_sku text=null;movement_count bigint;move_value numeric(30,2);
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='Canonical inventory unavailable in this business';end if;if data_mode is null or as_of is null or not isfinite(as_of) or barcode_search is not null and(length(barcode_search)>180 or length(btrim(barcode_search))=0) or page_size is null or page_size not between 1 and 200 or after_sku is not null and(event_ceiling is null or ledger_ceiling is null) then raise exception 'Choose a complete inventory date/page/snapshot context';end if;
 select * into config from public.billing_inventory_configs where business_id=business and demo=data_mode;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type) order by code),'[]'::jsonb) into accounts from public.billing_ledger_accounts where business_id=business and demo=data_mode;
 select coalesce(max(sequence),0) into max_event from public.billing_inventory_events where business_id=business and demo=data_mode;select next_number-1 into max_ledger from public.billing_ledger_configs where business_id=business and demo=data_mode;
 event_ceiling=coalesce(event_ceiling,max_event);ledger_ceiling=coalesce(ledger_ceiling,max_ledger,0);if event_ceiling<0 or event_ceiling>max_event or ledger_ceiling<0 or ledger_ceiling>coalesce(max_ledger,0) then raise exception 'Invalid stock review snapshot';end if;
 select count(*) into count from public.billing_inventory_items where business_id=business and demo=data_mode;
 select coalesce(jsonb_agg(to_jsonb(i)||jsonb_build_object('reorder_level',i.reorder_level::text,'overstock_level',i.overstock_level::text,'onHand',coalesce((select sum(m.quantity) from public.billing_inventory_movements m join public.billing_inventory_events e on e.id=m.event_id where m.item_id=i.id and m.date<=as_of and e.sequence<=event_ceiling),0)::numeric(30,6)::text,'reserved',coalesce((select sum(r.quantity*case when r.kind='reserve' then 1 else -1 end) from public.billing_inventory_reservations r where r.item_id=i.id and r.date<=as_of),0)::numeric(30,6)::text,'value',coalesce((select sum(m.value) from public.billing_inventory_movements m join public.billing_inventory_events e on e.id=m.event_id where m.item_id=i.id and m.date<=as_of and e.sequence<=event_ceiling),0)::numeric(30,2)::text) order by i.sku),'[]'::jsonb) into items from(select * from public.billing_inventory_items where business_id=business and demo=data_mode and(after_sku is null or sku>after_sku) and(barcode_search is null or barcode=barcode_search) order by sku limit page_size+1)i;
 if jsonb_array_length(items)>page_size then next_sku=items->(page_size-1)->>'sku';items=items-page_size;end if;
 select coalesce(jsonb_agg(to_jsonb(w) order by code),'[]'::jsonb) into warehouses from public.billing_inventory_warehouses w where business_id=business and demo=data_mode;if jsonb_array_length(warehouses)>500 then raise exception 'Warehouse review exceeds500; no partial warehouse selection shown';end if;
 if item_id is not null then
  select * into selected from public.billing_inventory_items i where i.id=item_id and i.business_id=business and i.demo=data_mode;if selected.id is null then raise exception using errcode='P0002',message='Canonical item unavailable in this business/data mode';end if;
  with balances as(select m.warehouse_id,m.lot_id,sum(m.quantity) quantity,sum(m.value) value from public.billing_inventory_movements m join public.billing_inventory_events e on e.id=m.event_id where m.item_id=selected.id and m.date<=as_of and e.sequence<=event_ceiling group by m.warehouse_id,m.lot_id),held as(select b.*,coalesce((select sum(r.quantity*case when r.kind='reserve' then 1 else -1 end) from public.billing_inventory_reservations r where r.item_id=selected.id and r.warehouse_id=b.warehouse_id and r.lot_id=b.lot_id and r.date<=as_of),0) lot_reserved,coalesce((select sum(r.quantity*case when r.kind='reserve' then 1 else -1 end) from public.billing_inventory_reservations r where r.item_id=selected.id and r.warehouse_id=b.warehouse_id and r.lot_id is null and r.date<=as_of),0) generic_reserved,coalesce((select min(l.fifo_date) from public.billing_inventory_layers l where l.item_id=selected.id and l.warehouse_id=b.warehouse_id and l.lot_id=b.lot_id and l.date<=as_of),as_of) fifo_date from balances b),assigned as(select b.*,greatest(0,least(b.quantity-b.lot_reserved,b.generic_reserved-coalesce(sum(b.quantity-b.lot_reserved) over(partition by b.warehouse_id order by b.fifo_date,b.lot_id rows between unbounded preceding and 1 preceding),0))) assigned_reserved from held b)
  select coalesce(jsonb_agg(jsonb_build_object('warehouseId',b.warehouse_id,'lotId',b.lot_id,'quantity',b.quantity::numeric(30,6)::text,'reserved',(b.lot_reserved+b.assigned_reserved)::numeric(30,6)::text,'available',(b.quantity-b.lot_reserved-b.assigned_reserved)::numeric(30,6)::text,'value',b.value::numeric(30,2)::text,'expired',l.expires_on is not null and l.expires_on<as_of) order by b.warehouse_id,b.lot_id),'[]'::jsonb) into stock from assigned b join public.billing_inventory_lots l on l.id=b.lot_id;
  select coalesce(jsonb_agg(to_jsonb(u)||jsonb_build_object('factor',u.factor::text) order by u.code),'[]'::jsonb) into units from public.billing_inventory_units u where u.item_id=selected.id;
  select coalesce(jsonb_agg(to_jsonb(l) order by l.code),'[]'::jsonb) into lots from public.billing_inventory_lots l where l.item_id=selected.id;
  if jsonb_array_length(lots)>1000 then raise exception 'Selected item has over1000 lots/serials; a paged trace export is required, no partial choices shown';end if;
  select count(*) into movement_count from public.billing_inventory_movements m join public.billing_inventory_events e on e.id=m.event_id where m.item_id=selected.id and e.sequence<=event_ceiling;
  select coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('quantity',m.quantity::text,'value',m.value::text,'kind',e.kind,'eventSequence',e.sequence::text) order by m.date desc,e.sequence desc,m.id),'[]'::jsonb) into movements from(select * from public.billing_inventory_movements m where m.item_id=selected.id order by m.date desc,m.id desc limit 200)m join public.billing_inventory_events e on e.id=m.event_id where e.sequence<=event_ceiling;
  select coalesce(jsonb_agg(to_jsonb(l)||jsonb_build_object('quantity',l.quantity::text,'value',l.value::text,'remainingQuantity',(l.quantity-coalesce((select sum(c.quantity) from public.billing_inventory_consumptions c join public.billing_inventory_events e on e.id=c.event_id where c.layer_id=l.id and c.date<=as_of and e.sequence<=event_ceiling),0))::numeric(30,6)::text,'remainingValue',(l.value-coalesce((select sum(c.value) from public.billing_inventory_consumptions c join public.billing_inventory_events e on e.id=c.event_id where c.layer_id=l.id and c.date<=as_of and e.sequence<=event_ceiling),0))::numeric(30,2)::text) order by l.fifo_date,l.sequence),'[]'::jsonb) into layers from public.billing_inventory_layers l join public.billing_inventory_movements m on m.id=l.movement_id join public.billing_inventory_events e on e.id=m.event_id where l.item_id=selected.id and l.date<=as_of and e.sequence<=event_ceiling;
  if jsonb_array_length(layers)>1000 then raise exception 'Item cost layers exceed1000; no partial FIFO detail shown';end if;
  select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('quantity',c.quantity::text,'value',c.value::text,'kind',e.kind,'remainingReturnable',(c.quantity-coalesce((select sum(x.quantity) from public.billing_inventory_layers x where x.return_of=c.id),0))::numeric(30,6)::text) order by c.date,c.id),'[]'::jsonb) into consumptions from public.billing_inventory_consumptions c join public.billing_inventory_movements m on m.id=c.movement_id join public.billing_inventory_events e on e.id=c.event_id where m.item_id=selected.id;
  if jsonb_array_length(consumptions)>1000 then raise exception 'Item cost consumptions exceed1000; no partial return choices shown';end if;
  select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('quantity',r.quantity::text,'remaining',case when r.kind='reserve' then r.quantity-coalesce((select sum(x.quantity) from public.billing_inventory_reservations x where x.reservation_id=r.id),0) else 0 end::numeric(30,6)::text) order by r.date,r.id),'[]'::jsonb) into reservations from public.billing_inventory_reservations r where r.item_id=selected.id;if jsonb_array_length(reservations)>1000 then raise exception 'Item reservations exceed1000; no partial reservation history shown';end if;
  select coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('quantity',s.quantity::text,'value',s.value::text) order by s.date,s.id),'[]'::jsonb) into sources from public.billing_inventory_source_lines s where s.item_id=selected.id;if jsonb_array_length(sources)>1000 then raise exception 'Item source links exceed1000; no partial fulfillment context shown';end if;
 end if;
 reconciliation=public.billing_inventory_reconciliation(business,data_mode,as_of,event_ceiling,ledger_ceiling);
 return jsonb_build_object('businessId',business,'demo',data_mode,'asOf',as_of,'configured',config.business_id is not null,'config',case when config.business_id is null then null else to_jsonb(config) end,'currency',coalesce(config.currency,(select currency from public.billing_ledger_configs where business_id=business and demo=data_mode)),'ledgerConfigured',max_ledger is not null,'canWrite',public.billing_can_access(business,true),'canManage',public.billing_is_owner(business),'accounts',accounts,'warehouses',warehouses,'items',items,'itemCount',count,'barcodeSearch',barcode_search,'afterSku',after_sku,'nextSku',next_sku,'eventCeiling',event_ceiling::text,'ledgerCeiling',ledger_ceiling::text,'item',case when selected.id is null then null else to_jsonb(selected)||jsonb_build_object('reorder_level',selected.reorder_level::text,'overstock_level',selected.overstock_level::text) end,'stock',stock,'reservationScope','Current recorded reservation history by effective date; unassigned warehouse holds are distributed once across FIFO lot capacities for this view. Event/ledger snapshots do not freeze later reservation records; source/consumption/return choices include all recorded dates.','units',units,'lots',lots,'movements',movements,'movementCount',coalesce(movement_count,0),'movementsTruncated',coalesce(movement_count,0)>200,'layers',layers,'consumptions',consumptions,'reservations',reservations,'sources',sources,'reconciliation',reconciliation,'legacyQuantitiesImported',false);
end$$;
create function public.billing_inventory_fulfill(business uuid,data_mode boolean,command_id uuid,fulfillment_line_id uuid,warehouse_id uuid,kind text,movement_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
<<fulfill>>
declare prior public.billing_inventory_commands;source jsonb;item public.billing_inventory_items;base_unit public.billing_inventory_units;source_line public.billing_inventory_source_lines;lot public.billing_inventory_lots;consumed record;linked jsonb;result jsonb;lines jsonb='[]';entry jsonb;serial text;remaining numeric(24,6);take numeric(24,6);day date;qty numeric(24,6);order_line uuid;original_fulfillment uuid;
begin
 if auth.uid() is null or not public.billing_can_access(business,true) then raise exception using errcode='42501',message='Your role cannot post inventory fulfillment';end if;
 if data_mode is null or command_id is distinct from fulfillment_line_id or kind is null or kind not in ('dispatch','customer-return') or jsonb_typeof(movement_data) is distinct from 'object' then raise exception 'Stock fulfillment requires its immutable authority as command identity';end if;
 select * into prior from public.billing_inventory_commands c where c.business_id=business and c.demo=data_mode and c.command_id=billing_inventory_fulfill.command_id;
 if prior.command_id is not null then if prior.actor_id<>auth.uid() then raise exception using errcode='40001',message='Fulfillment command belongs to another actor';end if;return prior.result||jsonb_build_object('replayed',true,'stockEffect','posted','fulfillmentLineId',fulfillment_line_id);end if;
 perform public.billing_ledger_writer_lock(business,false);perform 1 from public.billing_ledger_configs where business_id=business and demo=data_mode for update;
 select * into prior from public.billing_inventory_commands c where c.business_id=business and c.demo=data_mode and c.command_id=billing_inventory_fulfill.command_id;
 if prior.command_id is not null then if prior.actor_id<>auth.uid() then raise exception using errcode='40001',message='Fulfillment command belongs to another actor';end if;return prior.result||jsonb_build_object('replayed',true,'stockEffect','posted','fulfillmentLineId',fulfillment_line_id);end if;
 if coalesce(movement_data->>'orderLineId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(movement_data->>'itemId','')!~'^[0-9a-fA-F-]{36}$' then raise exception 'Choose frozen sales-order line and item identity';end if;
 order_line=(movement_data->>'orderLineId')::uuid;source=public.billing_sales_inventory_source(business,data_mode,order_line);day=public.billing_payment_date(movement_data->'date');qty=public.billing_inventory_quantity(movement_data->'baseQuantity');
 select * into item from public.billing_inventory_items i where i.id=(movement_data->>'itemId')::uuid and i.business_id=business and i.demo=data_mode;
 if item.id is null or source->>'itemId'<>item.id::text or source->>'unitId' is distinct from movement_data->>'unitId' or qty<=0 then raise exception 'Frozen order item/UOM/base quantity differs';end if;
 perform public.billing_sales_inventory_authorize(fulfillment_line_id,business,data_mode,item.id,order_line,warehouse_id,kind,qty,day);
 if item.kind='service' then return jsonb_build_object('stockEffect','none-service','fulfillmentLineId',fulfillment_line_id,'replayed',false);end if;
 select * into base_unit from public.billing_inventory_units u where u.item_id=item.id and u.factor=1 and u.code=item.base_unit;
 if base_unit.id is null then raise exception 'Canonical base unit missing';end if;
 select * into source_line from public.billing_inventory_source_lines s where s.business_id=business and s.demo=data_mode and s.source_kind='sales-order' and s.source_id=order_line and s.line=0;
 if source_line.id is null then linked=public.billing_inventory_command(business,data_mode,gen_random_uuid(),'link',jsonb_build_object('sourceKind','sales-order','sourceId',order_line,'line',0,'itemId',item.id,'unitId',source->>'unitId','reviewed',true));select * into source_line from public.billing_inventory_source_lines where id=(linked->>'sourceLineId')::uuid;end if;
 if kind='dispatch' then
  if item.tracking='serial' then
   if qty<>trunc(qty) or jsonb_typeof(movement_data->'serials') is distinct from 'array' or jsonb_array_length(movement_data->'serials')<>qty or(select count(distinct value#>>'{}') from jsonb_array_elements(movement_data->'serials'))<>qty then raise exception 'Select one distinct recorded serial per base unit';end if;
   for entry in select value from jsonb_array_elements(movement_data->'serials') loop serial=entry#>>'{}';select * into lot from public.billing_inventory_lots l where l.item_id=item.id and l.code=serial;if lot.id is null then raise exception 'Recorded serial unavailable for this item';end if;lines=lines||jsonb_build_array(jsonb_build_object('itemId',item.id,'unitId',base_unit.id,'warehouseId',warehouse_id,'quantity','1','lotId',lot.id,'sourceLineId',source_line.id,'fulfillmentLineId',fulfillment_line_id));end loop;
  else
   entry=jsonb_build_object('itemId',item.id,'unitId',base_unit.id,'warehouseId',warehouse_id,'quantity',qty::text,'sourceLineId',source_line.id,'fulfillmentLineId',fulfillment_line_id);
   if item.tracking='batch' then select * into lot from public.billing_inventory_lots l where l.item_id=item.id and l.code=movement_data->>'batchCode';if lot.id is null then raise exception 'Choose an exact recorded batch for fulfillment';end if;entry=entry||jsonb_build_object('lotId',lot.id);end if;lines=jsonb_build_array(entry);
  end if;
 else
  if coalesce(movement_data->>'returnsFulfillmentLineId','')!~'^[0-9a-fA-F-]{36}$' then raise exception 'Return requires the original dispatch fulfillment identity';end if;original_fulfillment=(movement_data->>'returnsFulfillmentLineId')::uuid;remaining=qty;
  if item.tracking='serial' and(jsonb_typeof(movement_data->'serials') is distinct from 'array' or jsonb_array_length(movement_data->'serials')<>qty or(select count(distinct value#>>'{}') from jsonb_array_elements(movement_data->'serials'))<>qty) then raise exception 'Choose exact returned serials';end if;
  for consumed in select c.*,l.lot_id,b.code,c.quantity-coalesce((select sum(x.quantity) from public.billing_inventory_layers x where x.return_of=c.id),0) returnable from public.billing_inventory_consumptions c join public.billing_inventory_movements m on m.id=c.movement_id join public.billing_inventory_layers l on l.id=c.layer_id join public.billing_inventory_lots b on b.id=l.lot_id where c.business_id=business and c.demo=data_mode and m.item_id=item.id and m.fulfillment_line=original_fulfillment and m.source_line=source_line.id and(item.tracking<>'batch' or b.code=movement_data->>'batchCode') and(item.tracking<>'serial' or exists(select 1 from jsonb_array_elements(movement_data->'serials')s where s.value#>>'{}'=b.code)) order by c.date,l.fifo_date,l.sequence,c.id loop
   if remaining=0 then exit;end if;if consumed.returnable<=0 then continue;end if;take=least(remaining,consumed.returnable);lines=lines||jsonb_build_array(jsonb_build_object('itemId',item.id,'unitId',base_unit.id,'warehouseId',warehouse_id,'quantity',take::text,'returnOf',consumed.id,'fulfillmentLineId',fulfillment_line_id));remaining=remaining-take;
  end loop;if remaining>0 then raise exception 'Returned units exceed original dispatch cost-consumption/serial provenance';end if;
 end if;
 if jsonb_array_length(lines)>50 then raise exception 'Fulfillment needs over50 physical cost/serial segments; split into reviewed fulfillment commands';end if;
 result=public.billing_inventory_command(business,data_mode,command_id,'move',jsonb_build_object('kind',kind,'date',day,'reason',coalesce(nullif(movement_data->>'reason',''),'Sales fulfillment '||fulfillment_line_id::text),'costReviewed',true,'lines',lines));return result||jsonb_build_object('stockEffect','posted','fulfillmentLineId',fulfillment_line_id);
end$$;
DO $$declare fn regprocedure;begin for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'billing_inventory_%' loop execute format('revoke all on function %s from public,anon,authenticated',fn);end loop;end$$;
grant execute on function public.billing_inventory_setup(uuid,boolean,date,jsonb,text,boolean),public.billing_inventory_command(uuid,boolean,uuid,text,jsonb),public.billing_inventory_read(uuid,boolean,date,uuid,text,integer,bigint,bigint,text),public.billing_inventory_reconciliation(uuid,boolean,date,bigint,bigint) to authenticated;
notify pgrst,'reload schema';
